-- Rollback for iso-9001-md-verification-pack.sql (2026-09-05).
-- Reverts ONLY rows this pack touched (identified by the verification_note tag) and ONLY for standard ISO-9001
-- (joined through worksheet_templates -> standards.code). The 2026-09-07 prod export showed all 69 active fields
-- carrying the single prior status 'imported_unverified' (0 verified_against_standard, 0 corrected), so every row
-- returns to exactly that status. ISO-9001 has 0 equations in prod, so there is no equations section.
-- No transaction control in this file: apply-pack.mjs supplies BEGIN/COMMIT and implements --dry-run by rolling back.

-- ---- fields (status + quote + note + verified_at) — prior status = imported_unverified (69 rows) ----
update public.fields f set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = f.worksheet_template_id and s.code = 'ISO-9001'
   and f.id in ('2cb4b548-5b38-4a74-89d0-fbc54e4272b1','9fa65aef-305e-4e71-8d07-7cfc33127b02','882ca046-a10c-468f-b1c2-cd392b23b230','24867d34-d87e-460b-a95e-d90cf2de0b46','d6d00fed-c1bd-4c1f-9f67-7ae841c6a436','96f483af-ecfd-409f-93a8-786d2097a6c6','407246b5-0522-4d9c-90aa-506966298b28','51f7fea2-c9f4-4a8b-9c63-9b9dea976b0f','39300d64-e9b4-42eb-af11-225825e10777','ec7a212d-76b1-4e45-94b6-6aa34f05cbde','ccb5464f-c964-42d5-94c2-60822d328879','f939c21f-b921-40ce-8b14-e89c6810394e','639ffdac-f337-4e38-b103-af32629485ce','486cb35c-aa8b-4758-a255-9dca5d103f6b','462ff64e-9394-400a-8723-1176e7b4c1bb','9df6e09d-5c1e-405a-9d78-c2d545b07f73','536dd796-07b4-422e-bc62-57036e044027','2dcbe2d5-d527-4eb6-9ce6-a86e4747eb86','708fa5dc-6a9e-4370-883b-0f66e904da03','10bfd296-3654-4428-82a5-3e2a21c4af8f','f74c05c5-4f4f-4462-86f3-55124a09162c','c603bdef-c20f-4536-84c4-0ba6399c472e','753c2352-e685-4c2d-be21-8ccece854ce8','42acba82-b427-4c62-8e73-5632a9dc92d5','295202b9-ffc3-46bb-974e-04f0ca8fdd23','912d59e7-8dbb-4aeb-a126-584106b1c6af','c33964e3-c0a4-446d-accd-84ece86779bc','fc6cb563-b0c8-4917-b35c-0be58c2fb78b','976339c5-5562-4975-9b0a-df15effc368c','db08c4ea-e6fb-4a16-bebf-19312c62815b','6e390c87-b03d-4354-8a2d-36ddf8d60860','6e542dd5-d0ae-4e56-89bd-c5bbd84983a5','e78dc6ed-06f7-43d5-b0ad-150ee8894cae','f328b70d-64d4-4090-bb9e-0040b49ffb7a','b71dc37c-d517-4fb6-b77d-23620802520a','40045d18-b43d-4678-8e14-a10b173b7202','83fc090d-2364-45bf-b48a-b705d42b97d8','fb7b8456-6577-4c45-8c9b-50ade6e94f7e','43af6670-011b-4816-8b23-62e827634299','6433884f-4adf-4200-a394-970302b32e42','d2d113eb-d240-4cbe-8074-ecbbde0fc40f','92637ae7-ce51-4614-aa79-c20770e01c5d','6230825b-211f-4a5e-ba6e-b8f920b689f5','713eccd5-15f1-4f7e-90a2-695110429280','43fc17f5-0d87-45fc-aa47-515012d6d0ce','d788127d-0dc9-4184-8ba4-dcd3a638eadc','3ca7d72b-e658-4d9e-80bf-938e57989084','2a936cdc-7a46-4e71-b707-39b7b8b830a2','e6cae208-449f-4c00-83ba-68574f05ba66','34e5db49-574f-4d45-9bdf-9f555f442ceb','46feb5f8-a9f5-47ab-9a21-2a16d7fc0